"""Client for the customer portal API: list files with checksums, download one file."""

from dataclasses import dataclass
from urllib.parse import quote

import httpx


@dataclass(frozen=True)
class RemoteFile:
    path: str
    sha256: str
    size: int | None


class PortalError(RuntimeError):
    pass


class PortalClient:
    def __init__(self, base_url: str, token: str, http: httpx.Client | None = None):
        if not base_url or not token:
            raise PortalError("SOONY_PORTAL_URL and SOONY_PORTAL_TOKEN must be set (see .env.example)")
        self._base = base_url.rstrip("/")
        self._http = http or httpx.Client(timeout=60.0)
        self._headers = {"Authorization": f"Bearer {token}"}

    def list_files(self) -> list[RemoteFile]:
        resp = self._http.get(f"{self._base}/api/v1/files", headers=self._headers)
        if resp.status_code != 200:
            raise PortalError(f"listing failed: HTTP {resp.status_code}: {resp.text[:200]}")
        body = resp.json()
        items = body.get("files", body) if isinstance(body, dict) else body
        files = []
        for item in items:
            size = item.get("bytes", item.get("size"))
            files.append(RemoteFile(path=item["path"], sha256=item["sha256"], size=size))
        return files

    def download(self, path: str) -> bytes:
        url = f"{self._base}/api/v1/files/{quote(path, safe='/')}"
        resp = self._http.get(url, headers=self._headers)
        if resp.status_code != 200:
            raise PortalError(f"download of {path} failed: HTTP {resp.status_code}")
        return resp.content

"""
Turn any portal file into something a model can read: text where the file has text, page images
where it does not (scans, photos). The parsers make no assumption about column names, delimiters
or languages; they only make the content readable.
"""

import io
import re
import zipfile
from dataclasses import dataclass, field
from pathlib import PurePosixPath

TEXT_SUFFIXES = {".csv", ".tsv", ".txt", ".md", ".json", ".xml", ".log", ".eml"}
IMAGE_TYPES = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp"}
MAX_IMAGE_SIDE = 1600
MAX_PDF_IMAGE_PAGES = 4
# A PDF page with less extracted text than this is treated as a scan.
MIN_TEXT_PER_PAGE = 40


@dataclass
class Image:
    media_type: str
    data: bytes


@dataclass
class Extracted:
    kind: str
    text: str
    images: list[Image] = field(default_factory=list)

    @property
    def needs_vision(self) -> bool:
        return bool(self.images)


def decode_text(data: bytes) -> str:
    for encoding in ("utf-8-sig", "utf-16", "cp1250", "latin-1"):
        try:
            text = data.decode(encoding)
        except UnicodeDecodeError:
            continue
        if encoding == "utf-16" and "\x00" in text:
            continue
        return text
    return data.decode("utf-8", errors="replace")


def extract(path: str, data: bytes) -> Extracted:
    suffix = PurePosixPath(path).suffix.lower()
    if suffix in TEXT_SUFFIXES:
        return Extracted(kind=suffix.lstrip("."), text=decode_text(data))
    if suffix in {".xlsx", ".xlsm"}:
        return Extracted(kind="xlsx", text=_xlsx_text(data))
    if suffix == ".docx":
        return Extracted(kind="docx", text=_docx_text(data))
    if suffix == ".pdf":
        return _pdf(data)
    if suffix in IMAGE_TYPES:
        return Extracted(kind="image", text="", images=[_fit_image(data, IMAGE_TYPES[suffix])])
    return Extracted(kind="binary", text=f"[unsupported file type {suffix or '(none)'}, {len(data)} bytes]")


def _xlsx_text(data: bytes) -> str:
    import openpyxl

    wb = openpyxl.load_workbook(io.BytesIO(data), data_only=True)
    parts = []
    for ws in wb.worksheets:
        parts.append(f"## Sheet: {ws.title}")
        for row in ws.iter_rows(values_only=True):
            if any(c is not None for c in row):
                parts.append(" | ".join("" if c is None else str(c) for c in row))
        for row in ws.iter_rows():
            for cell in row:
                if cell.comment:
                    parts.append(f"[comment {cell.coordinate}] {cell.comment.text}")
    return "\n".join(parts)


def _docx_text(data: bytes) -> str:
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        xml = z.read("word/document.xml").decode("utf-8", errors="replace")
    xml = re.sub(r"</w:p>", "\n", xml)
    return re.sub(r"<[^>]+>", "", xml).strip()


def _pdf(data: bytes) -> Extracted:
    from pypdf import PdfReader

    reader = PdfReader(io.BytesIO(data))
    pages = [(page.extract_text() or "").strip() for page in reader.pages]
    text = "\n\n".join(f"--- page {i + 1} ---\n{t}" for i, t in enumerate(pages))
    scanned = [i for i, t in enumerate(pages) if len(t) < MIN_TEXT_PER_PAGE]
    images = _render_pdf_pages(data, scanned[:MAX_PDF_IMAGE_PAGES]) if scanned else []
    if scanned and len(scanned) > MAX_PDF_IMAGE_PAGES:
        text += f"\n[{len(scanned) - MAX_PDF_IMAGE_PAGES} more scanned pages not rendered]"
    return Extracted(kind="pdf", text=text, images=images)


def _render_pdf_pages(data: bytes, page_indexes: list[int]) -> list[Image]:
    import pypdfium2 as pdfium

    pdf = pdfium.PdfDocument(data)
    images = []
    for i in page_indexes:
        pil = pdf[i].render(scale=1.5).to_pil()
        images.append(_pil_to_image(pil))
    return images


def _fit_image(data: bytes, media_type: str) -> Image:
    from PIL import Image as PILImage

    pil = PILImage.open(io.BytesIO(data))
    if max(pil.size) <= MAX_IMAGE_SIDE and media_type in {"image/png", "image/jpeg"}:
        return Image(media_type, data)
    return _pil_to_image(pil)


def _pil_to_image(pil) -> Image:
    pil = pil.convert("RGB")
    pil.thumbnail((MAX_IMAGE_SIDE, MAX_IMAGE_SIDE))
    buf = io.BytesIO()
    pil.save(buf, format="JPEG", quality=85)
    return Image("image/jpeg", buf.getvalue())

"""
OpenAI-compatible backend: OpenAI itself, or a local llama.cpp server (`llama-server --jinja`,
which speaks the same chat completions API with tool calls) via ASK_LLM_BASE_URL.
"""

import base64
import json
from collections.abc import Callable

from openai import OpenAI

from ask_soony.extract import Image
from ask_soony.llm import RunResult, Tool, ToolError, ToolHandler


class OpenAIBackend:
    def __init__(self, model: str, api_key: str = "", base_url: str = "", provider: str = "openai"):
        kwargs = {}
        if base_url:
            kwargs["base_url"] = base_url
        # Local servers ignore the key, but the SDK requires one.
        if api_key or base_url:
            kwargs["api_key"] = api_key or "local"
        self.client = OpenAI(max_retries=4, **kwargs)
        self.model = model
        self.provider = provider

    def run(
        self,
        system: str,
        text: str,
        images: list[Image],
        tools: list[Tool],
        handler: ToolHandler,
        should_stop: Callable[[], bool],
        max_turns: int = 12,
    ) -> RunResult:
        content: list[dict] = [{"type": "text", "text": text}]
        for img in images:
            b64 = base64.standard_b64encode(img.data).decode("ascii")
            content.append(
                {"type": "image_url", "image_url": {"url": f"data:{img.media_type};base64,{b64}"}}
            )
        messages: list[dict] = [
            {"role": "system", "content": system},
            {"role": "user", "content": content},
        ]
        tool_defs = [
            {
                "type": "function",
                "function": {"name": t.name, "description": t.description, "parameters": t.schema},
            }
            for t in tools
        ]
        calls = 0
        usage = {"input_tokens": 0, "output_tokens": 0}
        stop = "max_turns"
        final_text = ""
        for _ in range(max_turns):
            response = self.client.chat.completions.create(
                model=self.model, messages=messages, tools=tool_defs
            )
            if response.usage:
                usage["input_tokens"] += response.usage.prompt_tokens or 0
                usage["output_tokens"] += response.usage.completion_tokens or 0
            choice = response.choices[0]
            msg = choice.message
            stop = choice.finish_reason or "unknown"
            final_text = msg.content or ""
            messages.append(msg.model_dump(exclude_none=True))
            if not msg.tool_calls:
                break
            for call in msg.tool_calls:
                calls += 1
                try:
                    args = json.loads(call.function.arguments or "{}")
                    out = handler(call.function.name, args)
                except (ToolError, json.JSONDecodeError) as e:
                    out = f"Error: {e}"
                messages.append({"role": "tool", "tool_call_id": call.id, "content": out})
            if should_stop():
                stop = "submitted"
                break
        return RunResult(final_text=final_text, tool_calls=calls, stop_reason=stop, usage=usage)

"""
Notifiers: where the watcher reports changes and findings.

One small interface with interchangeable adapters, so the same events can go to the console,
a macOS notification, a Discord channel or any webhook (for example the product's own backend).
"""

import subprocess
import sys
from dataclasses import dataclass, field
from typing import Protocol

import httpx

SEVERITY_COLORS = {"critical": 0xB3261E, "high": 0xD97706, "medium": 0x2563EB, "low": 0x6B7280, "info": 0x6B7280}


@dataclass
class Event:
    kind: str  # changes | finding | error
    title: str
    body: str
    severity: str = "info"
    data: dict = field(default_factory=dict)


class Notifier(Protocol):
    def send(self, event: Event) -> None: ...


class ConsoleNotifier:
    def send(self, event: Event) -> None:
        print(f"[{event.severity.upper():8}] {event.title}\n{event.body}\n", file=sys.stderr)


class MacNotifier:
    def send(self, event: Event) -> None:
        script = 'display notification (system attribute "B") with title (system attribute "T")'
        env = {"T": f"ask-soony: {event.title}"[:120], "B": event.body[:240]}
        subprocess.run(["osascript", "-e", script], env=env, check=False, capture_output=True)


class DiscordNotifier:
    """Posts to a Discord channel through an incoming webhook URL."""

    def __init__(self, url: str, http: httpx.Client | None = None):
        self.url = url
        self.http = http or httpx.Client(timeout=15.0)

    def send(self, event: Event) -> None:
        embed = {
            "title": event.title[:256],
            "description": event.body[:4000],
            "color": SEVERITY_COLORS.get(event.severity, 0x6B7280),
        }
        self.http.post(self.url, json={"username": "ask-soony watcher", "embeds": [embed]})


class WebhookNotifier:
    """Generic JSON webhook, e.g. for the product backend or another chat tool."""

    def __init__(self, url: str, http: httpx.Client | None = None):
        self.url = url
        self.http = http or httpx.Client(timeout=15.0)

    def send(self, event: Event) -> None:
        self.http.post(
            self.url,
            json={
                "kind": event.kind,
                "title": event.title,
                "body": event.body,
                "severity": event.severity,
                "data": event.data,
            },
        )


class Fanout:
    def __init__(self, notifiers: list[Notifier]):
        self.notifiers = notifiers

    def send(self, event: Event) -> None:
        for n in self.notifiers:
            try:
                n.send(event)
            except Exception as e:  # a broken channel must not stop the watcher
                print(f"notifier {type(n).__name__} failed: {e}", file=sys.stderr)


def build_notifiers(names: list[str], discord_url: str = "", webhook_url: str = "") -> Fanout:
    out: list[Notifier] = []
    for name in names:
        if name == "console":
            out.append(ConsoleNotifier())
        elif name == "macos":
            out.append(MacNotifier())
        elif name == "discord":
            if not discord_url:
                raise ValueError("ASK_NOTIFIERS includes discord but ASK_DISCORD_WEBHOOK_URL is empty")
            out.append(DiscordNotifier(discord_url))
        elif name == "webhook":
            if not webhook_url:
                raise ValueError("ASK_NOTIFIERS includes webhook but ASK_WEBHOOK_URL is empty")
            out.append(WebhookNotifier(webhook_url))
        else:
            raise ValueError(f"unknown notifier {name!r}: use console, macos, discord or webhook")
    return Fanout(out)

"""
The deterministic loop: poll the portal, store new versions, analyse what changed, notify.
No LLM decides when or what to fetch; the model only reads and judges.
"""

import sys
import time

from ask_soony.agent import Analyst
from ask_soony.notify import Event, Fanout
from ask_soony.portal import PortalClient
from ask_soony.store import PollResult, Store, severity_at_least


def poll(store: Store, portal: PortalClient, analyze_baseline: bool = False) -> PollResult:
    listing = portal.list_files()
    for f in listing:
        if not store.has_blob(f.sha256):
            store.put_blob(f.sha256, portal.download(f.path))
    return store.record_listing(listing, analyze_baseline=analyze_baseline)


def describe_poll(result: PollResult) -> Event | None:
    if result.baseline:
        n = len(result.new) + len(result.changed)
        return Event("changes", "Baseline stored", f"Stored the current portal state as the baseline ({n} versions).")
    if not result.has_changes:
        return None
    lines = [f"+ {v.path}" for v in result.new]
    lines += [f"~ {v.path}" for v in result.changed]
    lines += [f"- {p}" for p in result.removed]
    title = f"{len(result.new)} new, {len(result.changed)} changed, {len(result.removed)} removed"
    return Event("changes", title, "\n".join(lines), severity="medium", data={"poll_id": result.poll_id})


def analyze_pending(
    store: Store, analyst: Analyst, notify: Fanout, min_severity: str, limit: int | None = None
) -> int:
    done = 0
    for version in store.pending(limit):
        try:
            outcome = analyst.analyze(version)
        except Exception as e:
            store.set_status(version.id, "error")
            notify.send(Event("error", f"Analysis failed: {version.path}", str(e)[:500], "low"))
            continue
        done += 1
        if outcome.result is None:
            notify.send(
                Event("error", f"No analysis submitted: {version.path}", f"stop reason {outcome.stop_reason}", "low")
            )
            continue
        print(
            f"analysed {version.path}: {len(outcome.result.get('findings') or [])} findings, "
            f"{outcome.tool_calls} tool calls, {outcome.usage}",
            file=sys.stderr,
        )
        for f in store.findings(status=None, analysis_id=outcome.analysis_id):
            if severity_at_least(f["severity"], min_severity):
                evidence = "\n".join(f"> {e.get('path')}: {e.get('quote')}" for e in f["evidence"][:3])
                body = f"{f['detail']}\n\nAction: {f['suggested_action']}\n\n{evidence}"
                notify.send(Event("finding", f"#{f['id']} {f['title']}", body, f["severity"], data=f))
    return done


def watch(
    store: Store,
    portal: PortalClient,
    analyst: Analyst | None,
    notify: Fanout,
    interval: int,
    min_severity: str,
    analyze_baseline: bool = False,
) -> None:
    while True:
        try:
            result = poll(store, portal, analyze_baseline=analyze_baseline)
            event = describe_poll(result)
            if event:
                notify.send(event)
            if analyst:
                analyze_pending(store, analyst, notify, min_severity)
        except KeyboardInterrupt:
            raise
        except Exception as e:  # keep watching through network hiccups
            notify.send(Event("error", "Poll failed", str(e)[:500], "low"))
        time.sleep(interval)

