"""
Web push for the installed dashboard (PWA): a critical card rings the phone with a notification;
tapping it opens the card with an "Answer" button that starts the voice conversation.

VAPID keys are generated once and kept in data/state/vapid.json (gitignored with data/).
Subscriptions are kept in data/state/push_subscriptions.json.
"""

import base64
import json
import os
from pathlib import Path

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

router = APIRouter()


def _state_dir() -> Path:
    root = Path(__file__).resolve().parents[2]
    return Path(os.environ.get("ASK_SOONY_STATE_DIR") or root / "data" / "state")


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()


def vapid() -> dict:
    """Load or create the VAPID key pair: PEM private key path and the public key for browsers."""
    path = _state_dir() / "vapid.json"
    pem = _state_dir() / "vapid_private.pem"
    if path.exists() and pem.exists():
        return json.loads(path.read_text())
    pem.parent.mkdir(parents=True, exist_ok=True)
    key = ec.generate_private_key(ec.SECP256R1())
    pem.write_bytes(
        key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.PKCS8,
            serialization.NoEncryption(),
        )
    )
    os.chmod(pem, 0o600)
    public = key.public_key().public_bytes(
        serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint
    )
    data = {"public_key": _b64url(public), "private_pem": str(pem)}
    path.write_text(json.dumps(data))
    return data


def _subs_path() -> Path:
    return _state_dir() / "push_subscriptions.json"


def subscriptions() -> list[dict]:
    try:
        return json.loads(_subs_path().read_text())
    except (OSError, ValueError):
        return []


def send(title: str, body: str, card_id: str | None = None) -> dict:
    """Push to every subscribed device; drop subscriptions the push service reports as gone."""
    from pywebpush import WebPushException, webpush

    keys = vapid()
    claims_sub = os.environ.get("ASK_PUSH_CONTACT", "https://ask-soony.example.com")
    payload = json.dumps({"title": title, "body": body, "card_id": card_id})
    kept, sent, failed = [], 0, []
    for sub in subscriptions():
        try:
            webpush(sub, payload, vapid_private_key=REDACTED, vapid_claims={"sub": claims_sub}, ttl=600)
            kept.append(sub)
            sent += 1
        except WebPushException as e:
            status = getattr(e.response, "status_code", None)
            if status not in (404, 410):  # 404/410: subscription expired, forget it
                kept.append(sub)
            failed.append(str(status or e)[:120])
    _subs_path().write_text(json.dumps(kept))
    return {"sent": sent, "failed": failed}


@router.get("/api/push/key")
def push_key():
    return {"public_key": vapid()["public_key"]}


class Subscription(BaseModel):
    endpoint: str
    keys: dict


@router.post("/api/push/subscribe")
def push_subscribe(sub: Subscription):
    subs = [s for s in subscriptions() if s.get("endpoint") != sub.endpoint]
    subs.append(sub.model_dump())
    _subs_path().parent.mkdir(parents=True, exist_ok=True)
    _subs_path().write_text(json.dumps(subs))
    return {"devices": len(subs)}


class TestPush(BaseModel):
    card_id: str | None = None


@router.post("/api/push/test")
def push_test(body: TestPush):
    from ask_soony import api  # late import: api includes this router

    cards = api.get_state()["cards"]
    card = next((c for c in cards if c.get("id") == body.card_id), None) or (cards[0] if cards else None)
    if not subscriptions():
        raise HTTPException(409, "no device has enabled alerts yet")
    title = "🔴 Launch at risk"
    text = card["title"] if card else "Test alert"
    return send(title, f"{text}. Tap to talk to the assistant.", card["id"] if card else None)

// Service worker: shows launch alerts and opens the card ready to answer when tapped.
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

self.addEventListener("push", (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { title: "Launch alert", body: event.data ? event.data.text() : "" };
  }
  event.waitUntil(
    self.registration.showNotification(data.title || "Launch alert", {
      body: data.body || "",
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      tag: data.card_id || "alert",
      requireInteraction: true,
      data: { card_id: data.card_id || null },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const card = event.notification.data && event.notification.data.card_id;
  const url = card ? `/?card=${encodeURIComponent(card)}&talk=1` : "/";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((wins) => {
      for (const w of wins) {
        if ("navigate" in w) return w.navigate(url).then((c) => c && c.focus());
      }
      return self.clients.openWindow(url);
    }),
  );
});

// PWA helpers: register the service worker and subscribe this device to launch alerts.

export async function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {
  if (!("serviceWorker" in navigator)) return null;
  try {
    return await navigator.serviceWorker.register("/sw.js");
  } catch {
    return null;
  }
}

function urlBase64ToUint8Array(base64: string): Uint8Array {
  const padded = (base64 + "=".repeat((4 - (base64.length % 4)) % 4)).replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(padded), (c) => c.charCodeAt(0));
}

export function pushSupported(): boolean {
  return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;
}

export async function enableAlerts(): Promise<string> {
  if (!pushSupported()) {
    return "This browser cannot receive alerts. On iPhone: Share → Add to Home Screen, then open the app.";
  }
  const permission = await Notification.requestPermission();
  if (permission !== "granted") return "Notifications were not allowed.";
  const reg = (await registerServiceWorker()) ?? (await navigator.serviceWorker.ready);
  const { public_key } = await fetch("/api/push/key").then((r) => r.json());
  const sub =
    (await reg.pushManager.getSubscription()) ??
    (await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(public_key) }));
  const res = await fetch("/api/push/subscribe", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(sub.toJSON()),
  });
  return res.ok ? "Alerts are on for this device." : `Could not save the subscription (${res.status}).`;
}

export async function sendTestAlert(cardId: string): Promise<string> {
  const res = await fetch("/api/push/test", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ card_id: cardId }),
  });
  if (!res.ok) return `Test alert failed: ${await res.text()}`;
  const out = await res.json();
  return out.sent ? `Test alert sent to ${out.sent} device(s). Lock your phone to see it.` : `Not delivered: ${out.failed?.join(", ")}`;
}

