1	import { useEffect, useRef, useState } from "react";
2	import { enableAlerts, pushSupported, registerServiceWorker, sendTestAlert } from "./push";
3	import type { ActionKind, Card } from "./types";
4	
5	// Voice conversation about one card with OpenAI gpt-realtime over WebRTC. The server mints a
6	// short-lived client secret; the decision goes through the normal card action endpoint.
7	
8	type Line = { who: "assistant" | "you" | "system"; text: string };
9	
10	const DECISION_TO_ACTION: Record<string, ActionKind> = {
11	  approve: "allow_once",
12	  reject: "dismiss",
13	  escalate: "edit",
14	};
15	
16	export default function VoiceCall({
17	  card,
18	  onAction,
19	  autoStart = false,
20	}: {
21	  card: Card;
22	  onAction: (id: string, action: ActionKind, note?: string) => void;
23	  autoStart?: boolean;
24	}) {
25	  const [status, setStatus] = useState<"idle" | "connecting" | "live" | "ended" | "error">("idle");
26	  const [lines, setLines] = useState<Line[]>([]);
27	  const pc = useRef<RTCPeerConnection | null>(null);
28	  const started = useRef(false);
29	  const add = (l: Line) => setLines((prev) => [...prev, l].slice(-12));
30	  const [info, setInfo] = useState("");
31	  // Opened from a push notification: show the card as an incoming call.
32	  const params = new URLSearchParams(location.search);
33	  const [ringing, setRinging] = useState(params.get("talk") === "1" && params.get("card") === card.id);
34	  useEffect(() => {
35	    void registerServiceWorker();
36	  }, []);
37	
38	  function hangUp() {
39	    pc.current?.getSenders().forEach((s) => s.track?.stop());
40	    pc.current?.close();
41	    pc.current = null;
42	    setStatus("ended");
43	  }
44	
45	  async function start() {
46	    if (started.current && status !== "ended" && status !== "error") return;
47	    started.current = true;
48	    setStatus("connecting");
49	    setLines([]);
50	    try {
51	      const res = await fetch(`/api/cards/${encodeURIComponent(card.id)}/voice`, { method: "POST" });
52	      if (!res.ok) throw new Error(await res.text());
53	      const { client_secret } = (await res.json()) as { client_secret: string };
54	
55	      const peer = new RTCPeerConnection();
56	      pc.current = peer;
57	      const audio = new Audio();
58	      audio.autoplay = true;
59	      peer.ontrack = (e) => (audio.srcObject = e.streams[0]);
60	      const mic = await navigator.mediaDevices.getUserMedia({
61	        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
62	      });
63	      mic.getTracks().forEach((t) => peer.addTrack(t, mic));
64	
65	      const dc = peer.createDataChannel("oai-events");
66	      let decided = false;
67	      dc.onopen = () => {
68	        setStatus("live");
69	        dc.send(JSON.stringify({ type: "response.create" })); // assistant speaks first
70	      };
71	      dc.onmessage = (ev) => {
72	        const msg = JSON.parse(ev.data);
73	        if (msg.type === "response.output_audio_transcript.done" || msg.type === "response.audio_transcript.done") {
74	          add({ who: "assistant", text: msg.transcript });
75	        } else if (msg.type === "conversation.item.input_audio_transcription.completed" && msg.transcript?.trim()) {
76	          add({ who: "you", text: msg.transcript });
77	        } else if (msg.type === "response.function_call_arguments.done" && msg.name === "record_decision") {
78	          const args = JSON.parse(msg.arguments || "{}");
79	          const action = DECISION_TO_ACTION[args.decision] ?? "edit";
80	          const note = [`voice: ${args.decision}`, args.note].filter(Boolean).join(" · ");
81	          onAction(card.id, action, note);
82	          add({ who: "system", text: `Decision recorded: ${args.decision}` });
83	          dc.send(JSON.stringify({
84	            type: "conversation.item.create",
85	            item: { type: "function_call_output", call_id: msg.call_id, output: JSON.stringify({ ok: true }) },
86	          }));
87	          dc.send(JSON.stringify({ type: "response.create" }));
88	          decided = true;
89	        } else if (msg.type === "response.function_call_arguments.done") {
90	          // Other tools run on the server; relay the result back to the model.
91	          const args = JSON.parse(msg.arguments || "{}");
92	          add({ who: "system", text: `Running ${msg.name}…` });
93	          fetch(`/api/cards/${encodeURIComponent(card.id)}/tool`, {
94	            method: "POST",
95	            headers: { "Content-Type": "application/json" },
96	            body: JSON.stringify({ name: msg.name, arguments: args }),
97	          })
98	            .then((r) => r.json())
99	            .catch((e) => ({ ok: false, error: String(e) }))
100	            .then((out) => {
101	              if (msg.name === "send_supplier_email" && out.ok) add({ who: "system", text: `Email sent to ${out.sent_to}` });
102	              if (msg.name === "escalate" && out.ok) add({ who: "system", text: "Escalated" });
103	              if (out.ok && msg.name !== "get_card_details") decided = true;
104	              dc.send(JSON.stringify({
105	                type: "conversation.item.create",
106	                item: { type: "function_call_output", call_id: msg.call_id, output: JSON.stringify(out) },
107	              }));
108	              dc.send(JSON.stringify({ type: "response.create" }));
109	            });
110	        } else if (msg.type === "response.done" && decided) {
111	          setTimeout(hangUp, 4000); // let the goodbye play out
112	        } else if (msg.type === "error") {
113	          add({ who: "system", text: `Error: ${msg.error?.message ?? "unknown"}` });
114	        }
115	      };
116	
117	      const offer = await peer.createOffer();
118	      await peer.setLocalDescription(offer);
119	      const sdp = await fetch("https://api.openai.com/v1/realtime/calls", {
120	        method: "POST",
121	        body: offer.sdp,
122	        headers: { Authorization: `Bearer ${client_secret}`, "Content-Type": "application/sdp" },
123	      });
124	      if (!sdp.ok) throw new Error(await sdp.text());
125	      await peer.setRemoteDescription({ type: "answer", sdp: await sdp.text() });
126	    } catch (e) {
127	      add({ who: "system", text: `Could not start: ${(e as Error).message.slice(0, 200)}` });
128	      setStatus("error");
129	      pc.current?.close();
130	    }
131	  }
132	
133	  if (autoStart && !started.current) void start();
134	
135	  const live = status === "connecting" || status === "live";
136	  if (ringing && !live) {
137	    return (
138	      <div className="rounded-lg border-2 border-danger bg-danger/5 p-4 text-center">
139	        <div className="text-xs font-semibold uppercase tracking-wide text-danger">Incoming launch alert</div>
140	        <div className="mt-1 text-base font-semibold">{card.title}</div>
141	        <div className="mt-4 flex justify-center gap-3">
142	          <button
143	            className="rounded-full bg-emerald-600 px-6 py-3 text-base font-semibold text-white"
144	            onClick={() => {
145	              setRinging(false);
146	              history.replaceState(null, "", `/?card=${encodeURIComponent(card.id)}`);
147	              void start();
148	            }}
149	          >
150	            Answer
151	          </button>
152	          <button
153	            className="rounded-full border border-slate-300 px-6 py-3 text-base"
154	            onClick={() => {
155	              setRinging(false);
156	              history.replaceState(null, "", `/?card=${encodeURIComponent(card.id)}`);
157	            }}
158	          >
159	            Later
160	          </button>
161	        </div>
162	      </div>
163	    );
164	  }
165	  return (
166	    <div className="rounded-md border border-slate-200 p-3">
167	      <div className="flex flex-wrap items-center gap-3">
168	        {!live ? (
169	          <button className="rounded-md bg-accent px-3 py-1.5 text-sm font-medium text-white" onClick={start}>
170	            Talk to the assistant
171	          </button>
172	        ) : (
173	          <button className="rounded-md border border-danger px-3 py-1.5 text-sm font-medium text-danger" onClick={hangUp}>
174	            Hang up
175	          </button>
176	        )}
177	        {pushSupported() && !live && (
178	          <>
179	            <button className="rounded-md border border-slate-300 px-3 py-1.5 text-sm" onClick={async () => setInfo(await enableAlerts())}>
180	              Enable call alerts on this device
181	            </button>
182	            <button className="rounded-md border border-slate-300 px-3 py-1.5 text-sm" onClick={async () => setInfo(await sendTestAlert(card.id))}>
183	              Send test alert
184	            </button>
185	          </>
186	        )}
187	        <span className="text-xs text-slate-500">
188	          {info && <span className="mr-2">{info}</span>}
189	          {status === "connecting" && "Connecting…"}
190	          {status === "live" && "Live: speak normally, decide with approve, escalate or reject"}
191	          {status === "ended" && "Call ended"}
192	          {status === "error" && "Call failed"}
193	        </span>
194	      </div>
195	      {lines.length > 0 && (
196	        <ul className="mt-3 space-y-1 text-sm">
197	          {lines.map((l, i) => (
198	            <li key={i} className={l.who === "you" ? "text-slate-500" : l.who === "system" ? "text-xs text-accent" : ""}>
199	              <span className="font-medium">{l.who === "assistant" ? "Assistant: " : l.who === "you" ? "You: " : ""}</span>
200	              {l.text}
201	            </li>
202	          ))}
203	        </ul>
204	      )}
205	    </div>
206	  );
207	}
