import { ArrowUp, Loader2, Sparkles } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'
import { body, call, type Routine, type Run } from './types'

// "Describe it": say what should happen, the agent draws it as a routine on the left (the same
// When / Only if / Then diagram every routine has) and tests it on today's inbox. Follow-ups
// change the draft. Nothing runs until it is switched on, and a new routine starts by asking.
// Same calm language as the rest of Routines: ink on the ground, soft surfaces, accent blue for
// the one action, green only for what a routine would do.

type Msg = { who: 'you' | 'agent'; text: string }

interface Props {
  /** The draft on the left, if any: follow-ups change it instead of starting a new one. */
  draft: { routine: Routine; preview: Run } | null
  onDraft: (d: { routine: Routine; preview: Run }) => void
  phone?: boolean
}

const EXAMPLES = [
  'When a delivery note disagrees with SAP, write to the supplier and ask me first',
  'When a shipment has had no update for 12 hours, ask the carrier where it is',
  'When the site count is older than 6 hours, ask them to count again',
]

/** "3 cases today" from a dry run's actions. */
function matched(run: Run): string {
  const n = new Set((run.did ?? []).map((d) => (d as { card?: string; shipment?: string }).card ?? (d as { shipment?: string }).shipment)).size
  if (!run.ok) return 'It did not run cleanly on today\'s inbox; see the test below the diagram.'
  return n === 0 ? 'Tested on today\'s inbox: nothing matches right now.' : `Tested on today's inbox: it would act on ${n} ${n === 1 ? 'case' : 'cases'}.`
}

export function Describe({ draft, onDraft, phone }: Props) {
  const [msgs, setMsgs] = useState<Msg[]>([])
  const [text, setText] = useState('')
  const [busy, setBusy] = useState(false)
  const end = useRef<HTMLDivElement>(null)
  const box = useRef<HTMLTextAreaElement>(null)
  useEffect(() => { end.current?.scrollIntoView({ block: 'nearest', behavior: 'smooth' }) }, [msgs, busy])
  useEffect(() => {
    const el = box.current
    if (!el) return
    el.style.height = 'auto'
    el.style.height = `${Math.min(el.scrollHeight, 140)}px`
  }, [text])

  async function send(words: string) {
    const said = words.trim()
    if (!said || busy) return
    setText('')
    setMsgs((m) => [...m, { who: 'you', text: said }])
    setBusy(true)
    try {
      const out = draft
        ? await call<{ after: Routine; note?: string; preview: Run }>('/api/routines/edit', { routine: body(draft.routine), instruction: said })
            .then((r) => ({ routine: r.after, preview: r.preview, note: r.note }))
        : await call<{ routine: Routine; note?: string; preview: Run }>('/api/routines/describe', { text: said })
      onDraft({ routine: out.routine, preview: out.preview })
      const lead = out.note?.trim() || (draft ? `Changed “${out.routine.name}”.` : `Drew “${out.routine.name}” on the left.`)
      setMsgs((m) => [...m, { who: 'agent', text: `${lead} ${matched(out.preview)} It starts by asking you; switch it on when it looks right.` }])
    } catch (e) {
      setMsgs((m) => [...m, { who: 'agent', text: `I could not write that as a routine: ${(e as Error).message}. Try saying when it should happen and what it should do.` }])
    } finally {
      setBusy(false)
    }
  }

  return (
    <aside
      aria-label="Describe a routine"
      className={cn('flex flex-col rounded-2xl bg-soft', phone ? 'mt-8' : 'sticky top-6 max-h-[calc(100vh-120px)]')}
    >
      <header className="flex items-center gap-2 px-5 pt-5">
        <Sparkles size={15} strokeWidth={1.75} className="text-routine" aria-hidden="true" />
        <h2 className="t-small font-medium text-ink">Describe it</h2>
      </header>
      <div className="scroll-thin min-h-0 flex-1 space-y-3 overflow-y-auto px-5 pb-2 pt-3">
        {msgs.length === 0 && (
          <>
            <p className="t-small text-ink-2">
              Say what should happen. I draw it as a routine on the left and test it on today's inbox. Nothing runs until you switch it on.
            </p>
            <div className="flex flex-col items-start gap-2 pt-1">
              {EXAMPLES.map((x) => (
                <button
                  key={x}
                  onClick={() => void send(x)}
                  disabled={busy}
                  className="t-small cursor-pointer rounded-xl bg-ground px-3 py-2 text-left text-ink-2 shadow-[0_0_0_1px_var(--color-hair)] hover:text-ink disabled:opacity-60"
                >
                  {x}
                </button>
              ))}
            </div>
          </>
        )}
        {msgs.map((m, i) => (
          <p
            key={i}
            className={cn(
              't-small max-w-[92%] rounded-2xl px-3.5 py-2.5',
              m.who === 'you' ? 'ml-auto bg-ink text-white' : 'bg-ground text-ink shadow-[0_0_0_1px_var(--color-hair)]',
            )}
          >
            {m.text}
          </p>
        ))}
        {busy && (
          <p className="t-small flex items-center gap-2 text-ink-3">
            <Loader2 size={14} className="animate-spin" /> {draft ? 'Changing the routine…' : 'Writing the routine and testing it…'}
          </p>
        )}
        <div ref={end} />
      </div>
      <form
        onSubmit={(e) => { e.preventDefault(); void send(text) }}
        className="m-3 flex items-end gap-2 rounded-xl bg-ground p-2 shadow-[0_0_0_1px_var(--color-hair)] focus-within:shadow-[0_0_0_2px_var(--color-accent)]"
      >
        <textarea
          ref={box}
          rows={1}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); void send(text) } }}
          placeholder={draft ? 'Change it in your words…' : 'When … then …'}
          aria-label={draft ? 'Change the routine' : 'Describe a routine'}
          className="t-small min-h-9 flex-1 resize-none bg-transparent px-2 py-1.5 text-ink outline-none placeholder:text-ink-3"
        />
        <button
          type="submit"
          disabled={busy || !text.trim()}
          aria-label="Send"
          className="grid h-9 w-9 shrink-0 cursor-pointer place-items-center rounded-lg bg-accent text-white disabled:opacity-40"
        >
          <ArrowUp size={17} />
        </button>
      </form>
    </aside>
  )
}

